"""The interval itself."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True, order=True)
class Interval:
    """A closed range over the integers: ``start`` and ``end`` are both covered.

    ``Interval(5, 5)`` is the single point 5, which is a real interval rather
    than an empty one — a booking that takes no time still exists.
    """

    start: int
    end: int

    def __post_init__(self) -> None:
        if self.end < self.start:
            raise ValueError(f"interval end {self.end} precedes start {self.start}")

    @property
    def length(self) -> int:
        """How many integers the interval covers."""
        return self.end - self.start + 1

    def covers(self, point: int) -> bool:
        return self.start <= point <= self.end

    def __str__(self) -> str:
        return f"{self.start}-{self.end}"


def covers(intervals: list[Interval], point: int) -> bool:
    """Is ``point`` covered by any of ``intervals``?"""
    return any(iv.covers(point) for iv in intervals)


def touches_or_overlaps(a: Interval, b: Interval) -> bool:
    """Do ``a`` and ``b`` belong to the same run of covered integers?

    True when they share a point, and also when they are merely adjacent —
    there is no uncovered integer between them, so a merged interval is the
    honest description of what is covered. ``a`` must not start after ``b``.
    """
    return b.start <= a.end + 1

"""Merging layers into resolved values."""

from __future__ import annotations

from typing import Any, Iterable

from .layers import layer_rank
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Layers are applied from lowest precedence to highest, using the single
    source of truth for precedence (:func:`settings.layers.layer_rank`), so a
    later (higher-precedence) layer always replaces an earlier one.

    Invalid values are not fatal on their own: every layer is visited and every
    coercion failure is collected, then reported together in one ``ValueError``.
    """
    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[str] = []

    for layer in sorted(layers, key=lambda layer: layer_rank(layer.name)):
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            try:
                value = coerce(raw, schema.type_of(key))
            except (ValueError, TypeError) as exc:
                errors.append(f"{key} (from {layer.name}): {exc}")
                continue
            resolved[key] = (value, layer.name)

    if errors:
        raise ValueError(
            "invalid setting value(s): " + "; ".join(errors)
        )

    return resolved

"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    The rendering is *type aware*: a value's type is part of its identity, so
    the number ``1`` and the string ``"1"`` never render the same.  Containers
    are rendered structurally rather than through ``repr`` so that a value
    nested several levels down is still comparable, and unordered containers
    (mappings and sets) are rendered in a sorted, order-independent way.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return "bool:" + ("true" if value else "false")
    if isinstance(value, int):
        return "int:" + str(value)
    if isinstance(value, float):
        return "float:" + repr(value)
    if isinstance(value, complex):
        return "complex:" + repr(value)
    if isinstance(value, str):
        return "str:" + repr(value)
    if isinstance(value, bytes):
        return "bytes:" + repr(value)
    if isinstance(value, bytearray):
        return "bytearray:" + repr(bytes(value))
    if isinstance(value, dict):
        items = sorted(
            f"{canonical(k)}={canonical(v)}" for k, v in value.items()
        )
        return "dict:{" + ",".join(items) + "}"
    if isinstance(value, list):
        return "list:[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, tuple):
        return "tuple:(" + ",".join(canonical(v) for v in value) + ")"
    if isinstance(value, (set, frozenset)):
        kind = "frozenset" if isinstance(value, frozenset) else "set"
        items = sorted(canonical(v) for v in value)
        return kind + ":{" + ",".join(items) + "}"
    return type(value).__name__ + ":" + repr(value)

"""The memoising decorator."""

from __future__ import annotations

import inspect
from functools import wraps
from typing import Any, Callable, TypeVar

from .key import build_key
from .store import MemoStore

F = TypeVar("F", bound=Callable[..., Any])

_DEFAULT_STORE = MemoStore()


def memoize(fn: F | None = None, *, store: MemoStore | None = None) -> Any:
    """Cache ``fn``'s results under keys built from each call's arguments."""
    def decorate(func: F) -> F:
        memo = store if store is not None else MemoStore()
        try:
            signature = inspect.signature(func)
        except (TypeError, ValueError):
            signature = None

        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            key = build_key(func.__name__, args, kwargs, signature=signature)
            return memo.get_or_compute(key, lambda: func(*args, **kwargs))

        wrapper.store = memo  # type: ignore[attr-defined]
        return wrapper  # type: ignore[return-value]

    if fn is not None:
        return decorate(fn)
    return decorate

