"""Merging layers into resolved values."""

from __future__ import annotations

from typing import Any, Iterable

from .layers import ordered_layers
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Layers are applied in the one precedence order defined by
    :data:`settings.layers.LAYER_ORDER`; a value from a later layer replaces one
    from an earlier layer.  Only the winning value of each key is validated, and
    every invalid value is reported together instead of stopping at the first.
    """
    winning: dict[str, tuple[Any, str]] = {}
    for layer in ordered_layers(layers):
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            winning[key] = (raw, layer.name)

    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[str] = []
    for key, (raw, source) in winning.items():
        try:
            value = coerce(raw, schema.type_of(key))
        except (TypeError, ValueError) as exc:
            errors.append(f"{key}: {exc}")
            continue
        resolved[key] = (value, source)

    if errors:
        raise ValueError("invalid setting value(s): " + "; ".join(errors))
    return resolved

"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    Containers are rendered structurally rather than through ``repr`` so that
    a value nested several levels down is still comparable.  Scalars carry a
    type tag so that values which merely *look* alike (``1`` and ``"1"``)
    render differently and therefore never collide.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return "bool:" + ("true" if value else "false")
    if isinstance(value, int):
        return f"int:{value}"
    if isinstance(value, float):
        return f"float:{value!r}"
    if isinstance(value, complex):
        return f"complex:{value!r}"
    if isinstance(value, str):
        return f"str:{value}"
    if isinstance(value, (bytes, bytearray)):
        return f"bytes:{bytes(value)!r}"
    if isinstance(value, dict):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
        )
        return "dict{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, list):
        return "list[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, tuple):
        return "tuple(" + ",".join(canonical(v) for v in value) + ")"
    if isinstance(value, (set, frozenset)):
        return "set{" + ",".join(sorted(canonical(v) for v in value)) + "}"
    return f"{type(value).__name__}:{value!r}"

"""Cache keys.

A key names a *call*: the function plus the argument values it was made with.
Two calls that ask for the same thing must land on the same key, whatever the
caller's spelling, and two calls that ask for different things must not.
"""

from __future__ import annotations

import inspect
from typing import Any, Callable, Mapping, Sequence

from .normalize import canonical


def _bound_items(
    signature: inspect.Signature,
    args: Sequence[Any],
    kwargs: Mapping[str, Any],
) -> list[tuple[str, Any]] | None:
    """Bind a call to parameter names, filling in defaults.

    Returns a list of ``(parameter_name, value)`` pairs ordered by parameter
    name, or ``None`` if the call cannot be bound to ``signature``.
    """
    try:
        bound = signature.bind(*args, **kwargs)
    except TypeError:
        return None
    bound.apply_defaults()
    return sorted(bound.arguments.items())


def build_key(
    fn_name: str,
    args: Sequence[Any] = (),
    kwargs: Mapping[str, Any] | None = None,
    signature: inspect.Signature | None = None,
) -> str:
    """Build the cache key for a call to ``fn_name``.

    When ``signature`` is supplied the call is bound to the function's
    parameters, so positional/keyword spelling, keyword order and defaulted
    parameters all collapse onto the same key.  Values are always rendered by
    :func:`canonical`, so distinct values never collide.
    """
    kwargs = kwargs or {}

    if signature is not None:
        items = _bound_items(signature, args, kwargs)
        if items is not None:
            rendered = ",".join(
                f"{name}={canonical(value)}" for name, value in items
            )
            return f"{fn_name}|({rendered})"

    positional = "(" + ",".join(canonical(a) for a in args) + ")"
    keywords = "{" + ",".join(
        f"{name}={canonical(value)}"
        for name, value in sorted(kwargs.items())
    ) + "}"
    return f"{fn_name}|{positional}|{keywords}"


def signature_of(func: Callable[..., Any]) -> inspect.Signature | None:
    """Return ``func``'s signature, or ``None`` if it cannot be inspected."""
    try:
        return inspect.signature(func)
    except (TypeError, ValueError):
        return None

