"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    Every value carries a type tag so that values which merely *look* alike
    (``1`` and ``"1"``, ``1`` and ``1.0``, a list and a tuple) never render to
    the same text.  Containers are rendered structurally rather than through
    ``repr`` so that a value nested several levels down is still comparable,
    and their elements are ordered canonically so that iteration order (for
    dicts and sets) cannot leak into the key.
    """
    if value is None:
        return "None"
    # bool must be checked before int: bool is a subclass of int.
    if isinstance(value, bool):
        return "bool:" + ("True" if value else "False")
    if isinstance(value, int):
        return "int:" + str(value)
    if isinstance(value, float):
        return "float:" + repr(value)
    if isinstance(value, complex):
        return "complex:" + repr(value)
    if isinstance(value, str):
        return "str:" + repr(value)
    if isinstance(value, (bytes, bytearray)):
        return type(value).__name__ + ":" + repr(bytes(value))
    if isinstance(value, dict):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
        )
        return "dict:{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, (list, tuple)):
        tag = "list" if isinstance(value, list) else "tuple"
        return tag + ":[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, (set, frozenset)):
        tag = "set" if isinstance(value, set) else "frozenset"
        return tag + ":{" + ",".join(sorted(canonical(v) for v in value)) + "}"
    return f"{type(value).__name__}:{value!r}"

