"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    The rendering is tagged with the value's type so that values which merely
    *look* alike (the integer ``1`` and the string ``"1"``) do not collide.
    Containers are rendered structurally rather than through ``repr`` so that
    a value nested several levels down is still comparable.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return f"bool:{value}"
    if isinstance(value, int):
        return f"int:{value}"
    if isinstance(value, float):
        return f"float:{value!r}"
    if isinstance(value, complex):
        return f"complex:{value!r}"
    if isinstance(value, str):
        return f"str:{value!r}"
    if isinstance(value, bytes):
        return f"bytes:{value!r}"
    if isinstance(value, dict):
        items = sorted((canonical(k), canonical(v)) for k, v in value.items())
        return "dict:{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, (list, tuple)):
        tag = "list" if isinstance(value, list) else "tuple"
        return f"{tag}:[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, (set, frozenset)):
        tag = "set" if isinstance(value, set) else "frozenset"
        return f"{tag}:{{" + ",".join(sorted(canonical(v) for v in value)) + "}"
    return f"{type(value).__name__}:{value!r}"

