"""Turning a stream of chunks into logical records."""

from __future__ import annotations

from typing import Iterable, Iterator

from .scan import NEWLINE, QUOTE


def _iter_chars(chunks: Iterable[str]) -> Iterator[str]:
    """Flatten a stream of chunks into a stream of characters."""
    for chunk in chunks:
        if chunk:
            yield from chunk


def iter_rows(chunks: Iterable[str], *, quote: str = QUOTE,
              newline: str = NEWLINE) -> Iterator[str]:
    """Yield logical records, without their terminator, from text chunks.

    The unit of work is a record, not a chunk: how the caller happened to slice
    the text must not change which records come out. Quoting state is carried
    across chunk boundaries, so a quoted field that straddles a boundary (or an
    escaped quote split across one) is handled exactly as if the text had been
    read in one piece.

    A stream that ends while a quoted field is still open is malformed and
    raises ``ValueError``; a quote closed by the final character is fine.
    """
    chars = _iter_chars(chunks)
    buffer: list[str] = []
    in_quotes = False
    pending: str | None = None

    while True:
        if pending is not None:
            char = pending
            pending = None
        else:
            try:
                char = next(chars)
            except StopIteration:
                break

        if char == quote:
            if in_quotes:
                try:
                    following = next(chars)
                except StopIteration:
                    following = None
                if following == quote:
                    # Two quotes inside a quoted field mean one literal quote.
                    buffer.append(quote)
                    continue
                # The quote closes the field; reprocess whatever followed it.
                in_quotes = False
                buffer.append(char)
                pending = following
            else:
                in_quotes = True
                buffer.append(char)
        elif char == newline and not in_quotes:
            yield "".join(buffer)
            buffer = []
        else:
            buffer.append(char)

    if in_quotes:
        raise ValueError("unterminated quoted field")
    if buffer:
        yield "".join(buffer)

