from __future__ import annotations

from typing import Any


def _escape(text: str) -> str:
    """Escape structural characters so nested values cannot run together."""
    out = []
    for ch in text:
        if ch in "\\,[]{}:":
            out.append("\\")
        out.append(ch)
    return "".join(out)


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    Values are tagged with their type so that values which merely *look*
    alike -- the number ``1`` and the string ``"1"`` -- never collide.
    Containers are rendered structurally rather than through ``repr`` so that
    a value nested several levels down is still comparable.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return "bool:" + ("true" if value else "false")
    if isinstance(value, int):
        return "int:" + str(value)
    if isinstance(value, float):
        return "float:" + repr(value)
    if isinstance(value, complex):
        return "complex:" + repr(value)
    if isinstance(value, str):
        return "str:" + _escape(value)
    if isinstance(value, bytes):
        return "bytes:" + value.hex()
    if isinstance(value, bytearray):
        return "bytearray:" + bytes(value).hex()
    if isinstance(value, dict):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
        )
        return "dict:{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, (list, tuple)):
        tag = "list" if isinstance(value, list) else "tuple"
        return tag + ":[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, (set, frozenset)):
        tag = "set" if isinstance(value, set) else "frozenset"
        items = sorted(canonical(v) for v in value)
        return tag + ":{" + ",".join(items) + "}"
    return type(value).__name__ + ":" + _escape(repr(value))

