from typing import Any, Iterable

from .layers import layer_rank
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Layers are ordered using the single precedence table in :mod:`settings.layers`,
    so the environment and explicit overrides can never disagree about which one
    wins. The winning raw value for each key is coerced afterwards; every invalid
    winner is collected and reported together instead of failing on the first.
    """
    # Determine the winning raw value per key first, honoring precedence.
    winners: dict[str, tuple[Any, str]] = {}
    for layer in sorted(layers, key=lambda layer: layer_rank(layer.name)):
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            winners[key] = (raw, layer.name)

    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[str] = []
    for key, (raw, name) in winners.items():
        try:
            resolved[key] = (coerce(raw, schema.type_of(key)), name)
        except (TypeError, ValueError) as exc:
            errors.append(f"{key}: {exc}")
    if errors:
        raise ValueError("invalid settings: " + "; ".join(errors))
    return resolved

"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def _tagged(tag: str, parts: list[str]) -> str:
    """Join already-canonical parts with a type tag and length prefixes.

    Length prefixes keep the rendering unambiguous: a value can never be
    confused with the concatenation of its neighbours, at any nesting depth.
    """
    return tag + str(len(parts)) + ":" + "".join(
        f"{len(part)}:{part}" for part in parts
    )


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    The rendering is *type sensitive*: ``1`` and ``"1"`` are different values
    and must render differently. Containers are rendered structurally rather
    than through ``repr`` so that a value nested several levels down is still
    comparable, and unordered containers are sorted so that their iteration
    order cannot leak into the key.
    """
    if value is None:
        return "n"
    # bool must be checked before int: bool is a subclass of int.
    if isinstance(value, bool):
        return "b" + ("1" if value else "0")
    if isinstance(value, int):
        return "i" + str(value)
    if isinstance(value, float):
        return "f" + repr(value)
    if isinstance(value, complex):
        return "c" + repr(value)
    if isinstance(value, str):
        return _tagged("s", [value])
    if isinstance(value, (bytes, bytearray)):
        return _tagged("y", [bytes(value).hex()])
    if isinstance(value, Mapping):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
        )
        return _tagged("d", [f"{k}={v}" for k, v in items])
    if isinstance(value, (set, frozenset)):
        parts = sorted(canonical(v) for v in value)
        return _tagged("e", parts)
    if isinstance(value, (list, tuple)):
        return _tagged("l", [canonical(v) for v in value])
    # Fall back to a type-qualified repr so that distinct objects with the
    # same ``str`` do not silently collide.
    return _tagged("r", [type(value).__qualname__, repr(value)])


