"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    Containers are rendered structurally rather than through ``repr`` so that
    a value nested several levels down is still comparable.  Every scalar is
    tagged with its type so that values which merely look alike (the number
    ``1`` and the string ``"1"``) never render the same text.
    """
    if value is None:
        return "N"
    # ``bool`` must be checked before ``int``: it is a subclass of ``int``.
    if isinstance(value, bool):
        return "b:" + ("true" if value else "false")
    if isinstance(value, int):
        return "i:" + str(value)
    if isinstance(value, float):
        return "f:" + repr(value)
    if isinstance(value, complex):
        return "c:" + repr(value)
    if isinstance(value, str):
        return "s:" + value
    if isinstance(value, (bytes, bytearray)):
        return "y:" + bytes(value).hex()
    if isinstance(value, dict):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
        )
        return "{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, (list, tuple)):
        tag = "l" if isinstance(value, list) else "t"
        return tag + "[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, (set, frozenset)):
        tag = "e" if isinstance(value, set) else "z"
        return tag + "(" + ",".join(sorted(canonical(v) for v in value)) + ")"
    return "o:" + type(value).__name__ + ":" + repr(value)

"""The paging query itself."""

from __future__ import annotations

from operator import itemgetter
from typing import Any, Callable, Iterable, Sequence

from .cursor import decode_cursor, encode_cursor


def _order_key(sort_key: Callable[[Any], Any], tiebreak: Callable[[Any], Any]):
    return lambda row: (sort_key(row), tiebreak(row))


def _resume_after(row: Any, key: Any, tie: Any, sort_key, tiebreak) -> bool:
    """Is ``row`` strictly after the position the cursor was cut at?"""
    return (sort_key(row), tiebreak(row)) > (key, tie)


def page(records: Iterable[Any], *, cursor: str | None = None, size: int = 3,
         sort_key: Callable[[Any], Any] = itemgetter("created_at"),
         tiebreak: Callable[[Any], Any] = itemgetter("id")) -> dict[str, Any]:
    """One page of ``records``, ordered by ``(sort_key, tiebreak)``.

    Returns ``{"items": [...], "next_cursor": str | None}``; ``next_cursor`` is
    ``None`` when the page is the last one, so a caller can page until it runs
    out instead of guessing how many pages there are.
    """
    if size < 1:
        raise ValueError("page size must be at least 1")
    ordered: Sequence[Any] = sorted(records, key=_order_key(sort_key, tiebreak))

    if cursor is not None:
        key, tie = decode_cursor(cursor)
        ordered = [r for r in ordered if _resume_after(r, key, tie, sort_key, tiebreak)]

    window = list(ordered[:size])
    next_cursor = None
    if window and len(ordered) > size:
        last = window[-1]
        next_cursor = encode_cursor(sort_key(last), tiebreak(last))
    return {"items": window, "next_cursor": next_cursor}

