"""Merging layers into resolved values."""

from __future__ import annotations

from typing import Any, Iterable

from .layers import layer_rank
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Layers are composed in the single documented precedence order defined by
    :data:`settings.layers.LAYER_ORDER` (lowest first), so a value from a
    higher-precedence layer replaces one from a lower layer. Every invalid
    value is collected and reported together instead of aborting on the first.
    """
    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[tuple[str, str, Exception]] = []

    for layer in sorted(layers, key=lambda layer: layer_rank(layer.name)):
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            try:
                value = coerce(raw, schema.type_of(key))
            except (TypeError, ValueError) as exc:
                errors.append((key, layer.name, exc))
                continue
            resolved[key] = (value, layer.name)

    if errors:
        details = "; ".join(
            f"{key} (from {layer}): {exc}" for key, layer, exc in errors
        )
        raise ValueError(
            f"invalid value for {len(errors)} setting(s): {details}"
        )

    # Every known setting has a winning layer, even when no layer set it.
    for setting in schema.settings:
        if setting.name not in resolved:
            resolved[setting.name] = (setting.default, "default")

    return resolved

