    are sorted so insertion order never leaks into the key.  Scalars carry a
    type tag so that values which merely look alike (``1`` and ``"1"``) do not
    collide.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return f"bool:{value}"
    if isinstance(value, int):
        return f"int:{value}"
    if isinstance(value, float):
        return f"float:{value!r}"
    if isinstance(value, complex):
        return f"complex:{value!r}"
    if isinstance(value, str):
        return f"str:{value}"
    if isinstance(value, bytes):
        return f"bytes:{value!r}"
    if isinstance(value, bytearray):
        return f"bytearray:{bytes(value)!r}"
    if isinstance(value, dict):
        items = sorted(
            (canonical(k), canonical(v)) for k, v in value.items()
