from __future__ import annotations

from typing import Any, Iterable

from .layers import layer_rank
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Precedence comes from :func:`settings.layers.layer_rank`, so there is a
    single definition of the layer order.  The value from the highest-precedence
    layer that defines a key wins, and only that winning value is coerced.

    Every invalid winning value is reported together in one ``ValueError``
    rather than failing on the first one encountered.
    """
    ordered = sorted(layers, key=lambda layer: layer_rank(layer.name))

    winning: dict[str, tuple[Any, str]] = {}
    for layer in ordered:
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            winning[key] = (raw, layer.name)

    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[str] = []
    for key, (raw, source) in winning.items():
        try:
            value = coerce(raw, schema.type_of(key))
        except (TypeError, ValueError) as exc:
            errors.append(f"{key}: {exc}")
            continue
        resolved[key] = (value, source)

    if errors:
        raise ValueError("invalid setting values: " + "; ".join(errors))

    return resolved

