from __future__ import annotations

from typing import Any, Iterable

from .layers import ordered_layers
from .schema import Schema, coerce


def resolve(layers: Iterable[Any], schema: Schema) -> dict[str, tuple[Any, str]]:
    """Resolve every known key to ``(value, name of the layer that won)``.

    Precedence comes from :data:`settings.layers.LAYER_ORDER` so there is a
    single definition of the order. Only the winning value for each key is
    coerced, and every invalid value is reported together rather than one at a
    time.
