    for layer in ordered_layers(layers):
        for key, raw in layer.items().items():
            if not schema.defines(key):
                continue  # a value for a setting this app does not know about
            winners[key] = (raw, layer.name)

    resolved: dict[str, tuple[Any, str]] = {}
    errors: list[str] = []
    for key, (raw, source) in winners.items():
        try:
            resolved[key] = (coerce(raw, schema.type_of(key)), source)
        except (ValueError, TypeError) as exc:
            errors.append(f"{key}: {exc}")

    if errors:
        raise ValueError("invalid setting values: " + "; ".join(errors))

    return resolved

"""Turning argument values into the text a cache key is made of."""

from __future__ import annotations

from typing import Any


def canonical(value: Any) -> str:
    """Render one argument value so equal values render equally.

    Containers are rendered structurally rather than through ``repr`` so that
    a value nested several levels down is still comparable.  Every scalar is
    tagged with its type so that values which merely *look* alike -- ``1`` and
    ``"1"``, ``True`` and ``1``, ``[1]`` and ``(1,)`` -- never collide.
    """
    if value is None:
        return "none"
    if isinstance(value, bool):
        return f"bool:{value!r}"
    if isinstance(value, int):
        return f"int:{value!r}"
    if isinstance(value, float):
        return f"float:{value!r}"
    if isinstance(value, complex):
        return f"complex:{value!r}"
    if isinstance(value, str):
        return f"str:{value!r}"
    if isinstance(value, bytes):
        return f"bytes:{value!r}"
    if isinstance(value, dict):
        items = sorted((canonical(k), canonical(v)) for k, v in value.items())
        return "{" + ",".join(f"{k}:{v}" for k, v in items) + "}"
    if isinstance(value, list):
        return "[" + ",".join(canonical(v) for v in value) + "]"
    if isinstance(value, tuple):
        return "(" + ",".join(canonical(v) for v in value) + ")"
    if isinstance(value, (set, frozenset)):
        tag = "set" if isinstance(value, set) else "frozenset"
        return tag + "(" + ",".join(sorted(canonical(v) for v in value)) + ")"
    return f"{type(value).__name__}:{value!r}"
